import pandas as pd
import matplotlib.pyplot as plt
import numpy as np
import os

# 1. Load Data
csv_file = 'data/results.csv'
if not os.path.exists(csv_file):
    print("Error: CSV file not found!")
    exit()

df = pd.read_csv(csv_file)

# 2. Setup the Plot
plt.figure(figsize=(10, 6))
bar_width = 0.25
threads = sorted(df['Threads'].unique())
index = np.arange(len(threads))

# 3. Define the groups
c2 = df[df['Implementation'] == 'client_2copy']['Throughput_Gbps']
c1 = df[df['Implementation'] == 'client_1copy']['Throughput_Gbps']
c0 = df[df['Implementation'] == 'client_0copy']['Throughput_Gbps']

# 4. Create Bars
plt.bar(index, c2, bar_width, label='2-Copy (Standard)', color='#FF9999', edgecolor='black')
plt.bar(index + bar_width, c1, bar_width, label='1-Copy (Sendmsg)', color='#66B2FF', edgecolor='black')
plt.bar(index + 2*bar_width, c0, bar_width, label='0-Copy (ZeroCopy)', color='#99FF99', edgecolor='black')

# 5. Labels and Titles
plt.xlabel('Number of Threads', fontweight='bold')
plt.ylabel('Throughput (Gbps)', fontweight='bold')
plt.title('Network Throughput Analysis: Copy vs Zero-Copy', fontsize=14)
plt.xticks(index + bar_width, threads)
plt.legend()
plt.grid(axis='y', linestyle='--', alpha=0.7)

# 6. Save
output_file = 'plots/throughput_comparison.png'
plt.savefig(output_file)
print(f"Plot saved to {output_file}")